static T unwrapOr<T>(Result<T, String> r, T d) {
    if (r.isOk()) {
        return r.value()
    }
    return d
}
static Int main() {
    Result<Int, String> a = Ok(5)
    Result<Int, String> b = Err("x")
    print(unwrapOr(a, 0))
    print(unwrapOr(b, 9))
    return 0
}

static T boxFirst<T>(T v) {
    T local = v
    List<T> box = [local]
    return box.get(0)
}
static Int main() { print(boxFirst<Int>(4)); return 0 }

